insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('rockphysics', 'advanced', 'module', 'm01-from-a-rock-to-an-interface', 1, 'What does the Expert tier add to the Professional tier''s work?', '["An overburden, which turns two rocks into two interfaces.", "A property model, letting the porosity vary across the field.", "A saturation height model, replacing the constant water saturation.", "A processing sequence, turning reflectivity into a recorded trace."]'::jsonb, 0, 'A reflection is not a property of a rock. It is a property of a boundary between two of them, and the tier below produced rocks rather than boundaries.'),
  ('rockphysics', 'advanced', 'module', 'm01-from-a-rock-to-an-interface', 2, 'What sits above the Ekene sand in this tier?', '["A second sand at 3200 m/s, 1800 m/s and 2250 kg/m3.", "A shale at 2743 m/s, 1394 m/s and 2450 kg/m3.", "A carbonate at 4500 m/s, 2500 m/s and 2600 kg/m3.", "Nothing. The sand is treated as a halfspace throughout."]'::jsonb, 1, 'The same shale sits over both fluid cases, so only the lower halfspace changes and every difference between the two responses is a fluid difference.'),
  ('rockphysics', 'advanced', 'module', 'm01-from-a-rock-to-an-interface', 3, 'What does a reflection at normal incidence depend on?', '["The contrast in velocity alone, since density cancels.", "The contrast in all three properties of both rocks.", "The contrast in acoustic impedance, and nothing else.", "The contrast in Poisson''s ratio across the interface."]'::jsonb, 2, 'At zero angle the incident wave produces no shear motion at the interface, so no shear property can influence it. Away from normal incidence all three contrasts matter.'),
  ('rockphysics', 'advanced', 'module', 'm01-from-a-rock-to-an-interface', 4, 'What are the two Ekene impedances against the shale''s?', '["7,200,000 brine and 5,923,875 gas against 6,720,350.", "6,720,350 brine and 5,923,875 gas against 7,200,000.", "7,200,000 brine and 6,720,350 gas against 5,923,875.", "5,923,875 brine and 7,200,000 gas against 6,720,350."]'::jsonb, 0, 'The brine sand is harder than the shale and the gas sand softer, so the reflection changes sign between the two cases.'),
  ('rockphysics', 'advanced', 'module', 'm01-from-a-rock-to-an-interface', 5, 'Is the Ekene gas sand faster or slower than the shale above it?', '["Slower, by 162.69722802961946 m/s.", "Faster, by 162.69722802961946 m/s exactly.", "The same, which is why the reflection is near zero.", "Slower, by 457 m/s, which is why the reflection flips."]'::jsonb, 1, 'The velocity contrast stays positive across the interface. The reflection is negative anyway, because the density falls by 411.29 kg/m3 and outweighs it.'),
  ('rockphysics', 'advanced', 'module', 'm01-from-a-rock-to-an-interface', 6, 'What actually flips the sign of the Ekene reflection?', '["The shear contrast, which reverses between the two cases.", "The velocity contrast, since the gas sand is slower than the shale.", "The density contrast, which outweighs the velocity contrast.", "The Poisson''s ratio contrast, which changes sign with the fluid."]'::jsonb, 2, 'The gas sand is 5.9 percent faster and 16.8 percent lighter than the shale, so the product falls 11.9 percent below the shale''s impedance.'),
  ('rockphysics', 'advanced', 'module', 'm01-from-a-rock-to-an-interface', 7, 'Which of the three contrasts across this interface changes sign on substitution?', '["The shear contrast, from negative to positive.", "The density contrast, from positive to negative.", "The velocity contrast, from positive to negative.", "None. All three keep their sign and change size."]'::jsonb, 3, 'The compressional contrast stays positive and weakens, the shear contrast stays positive and strengthens, and the density contrast stays negative and strengthens. Only the reflection coefficient changes sign.'),
  ('rockphysics', 'advanced', 'module', 'm01-from-a-rock-to-an-interface', 8, 'What is the exact normal incidence reflection for the Ekene gas case?', '["-0.0629911815139045.", "-0.06282494068620303, which is the Shuey intercept.", "-0.12239091302671612, the value at 30 degrees.", "+0.034457, which is the brine case."]'::jsonb, 0, '$(5{,}923{,}875 - 6{,}720{,}350)/(5{,}923{,}875 + 6{,}720{,}350)$. The Shuey intercept is the linearised version of it and differs in the fourth decimal.'),
  ('rockphysics', 'advanced', 'module', 'm01-from-a-rock-to-an-interface', 9, 'Could any assumed porosity make the Ekene gas reflection positive?', '["Yes, at a porosity below about 0.10.", "No. The gas impedance peaks at 6,138,917, below the shale''s.", "Yes, at a porosity above about 0.40.", "Yes, at any porosity outside 0.20 to 0.30."]'::jsonb, 1, 'The gas impedance rises with porosity to a maximum near 0.41 and falls again, never reaching the shale''s 6,720,350. The sign is robust, while the impedance sits 16.1 percent below the shale''s at a porosity of 0.20 and 9.9 percent below it at 0.30.'),
  ('rockphysics', 'advanced', 'module', 'm01-from-a-rock-to-an-interface', 10, 'Why does the shear velocity finally matter at this tier?', '["It sets the critical angle beyond which the solution goes complex.", "It is needed to compute the impedance of each rock.", "It enters the angle dependence, which the tier below had no use for.", "It determines the tuning thickness of the reservoir."]'::jsonb, 2, 'It has been carried untouched through two tiers because a fluid cannot change it. Here it enters the gradient, which is the coefficient that carries fluid information a stack cannot.'),
  ('rockphysics', 'advanced', 'module', 'm01-from-a-rock-to-an-interface', 11, 'What does the AVO panel''s frequency control change?', '["The class threshold applied to the intercept.", "Every reflection coefficient on the chart.", "The gradient but not the intercept.", "Only the wedge tuning tile at the bottom."]'::jsonb, 3, 'Reflectivity is a property of the interface and not of the wavelet. The wavelet decides what thickness of bed can be resolved, which is a different question.'),
  ('rockphysics', 'advanced', 'module', 'm01-from-a-rock-to-an-interface', 12, 'What do the solid and dashed lines on the panel show?', '["The exact Zoeppritz solution and the Shuey approximation.", "The brine case and the gas case.", "The two term and three term Shuey forms.", "The reflection and its uncertainty band."]'::jsonb, 0, 'Colour carries the fluid case, blue for brine and amber for gas. Where the two line styles part company, the approximation is failing.'),
  ('rockphysics', 'advanced', 'module', 'm01-from-a-rock-to-an-interface', 13, 'What are the four Ekene velocity ratios worth noticing?', '["Shale 1.537, brine sand 1.778, gas sand 1.968.", "Shale 1.968, brine sand 1.778, gas sand 1.537.", "All three near 1.8, which is why the reflections are weak.", "Shale 1.778, brine sand 1.968, gas sand 1.537."]'::jsonb, 1, 'The interface is a step down in velocity ratio in both cases and a bigger step in the gas case. Since the gradient is essentially a contrast in Poisson''s ratio, that step is where the gradient comes from.'),
  ('rockphysics', 'advanced', 'module', 'm01-from-a-rock-to-an-interface', 14, 'What does this tier inherit that it cannot test?', '["That the reflection is measured at the top of the reservoir.", "That the shale and sand velocities were logged correctly.", "That the logged point was brine saturated.", "That the wavelet is a Ricker of known frequency."]'::jsonb, 2, 'It is a petrophysical judgement made two tiers ago, and every rock in this tier descends from it. The porosity assumption is inherited too and its effect can at least be computed here.'),
  ('rockphysics', 'advanced', 'module', 'm01-from-a-rock-to-an-interface', 15, 'What does this tier deliberately not do?', '["Predict the class of the substituted rock.", "Compute the reflection at angles beyond normal incidence.", "Model both fluid cases under the same overburden.", "Process seismic data or invert a real gather."]'::jsonb, 3, 'Everything here is forward modelling: given two rocks, what should the data look like. The forward model is what an interpretation is compared against.'),
  ('rockphysics', 'advanced', 'module', 'm02-intercept-and-gradient', 1, 'What did Shuey''s 1985 rewrite of Zoeppritz achieve?', '["It separated the rocks from the angle.", "It made the exact solution faster to evaluate.", "It extended the exact solution past the critical angle.", "It removed the need for a shear velocity in the model."]'::jsonb, 0, 'Three coefficients built from the rocks alone, and three functions of angle that do not depend on the rocks. That separation is what makes a gather invertible.'),
  ('rockphysics', 'advanced', 'module', 'm02-intercept-and-gradient', 2, 'What is Shuey''s three term form?', '["$A + B\\sin^2\\theta + C\\tan^2\\theta$.", "$A + B\\sin^2\\theta + C(\\tan^2\\theta - \\sin^2\\theta)$.", "$A\\cos^2\\theta + B\\sin^2\\theta + C$.", "$A + B\\theta + C\\theta^2$."]'::jsonb, 1, 'The bracket is zero at zero angle and grows slowly, reaching 0.0833 at 30 degrees and 0.290913 at 40, which is why the third term is negligible at near offsets.'),
  ('rockphysics', 'advanced', 'module', 'm02-intercept-and-gradient', 3, 'Why can a gather be inverted for the Shuey coefficients?', '["The gather records enough offsets to determine six properties.", "The exact solution can be rearranged for the rock properties.", "A line fitted against $\\sin^2\\theta$ gives A and B.", "The wavelet is removed during processing, leaving reflectivity."]'::jsonb, 2, 'Two numbers extracted from a curve, and both are rock properties. Zoeppritz''s exact solution cannot be inverted because a curve cannot determine six independent numbers.'),
  ('rockphysics', 'advanced', 'module', 'm02-intercept-and-gradient', 4, 'Which rock property is absent from the intercept?', '["The shear velocity of either rock.", "The density of either rock.", "The compressional velocity of the lower rock.", "The porosity of the lower rock."]'::jsonb, 0, 'At normal incidence the incident wave produces no shear motion, so no shear property can influence the reflection. The shear velocity appears twice in the gradient instead.'),
  ('rockphysics', 'advanced', 'module', 'm02-intercept-and-gradient', 5, 'What are the two Ekene intercepts?', '["-0.06282494068620303 brine and 0.03434399848203321 gas.", "0.03434399848203321 brine and -0.06282494068620303 gas.", "0.034457 brine and -0.0629911815139045 gas.", "0.07689718997139491 brine and 0.028802610843132695 gas."]'::jsonb, 1, 'The exact normal incidence values are 0.034457 and -0.0629911815139045, close but not equal, and the last pair is the curvature coefficients.'),
  ('rockphysics', 'advanced', 'module', 'm02-intercept-and-gradient', 6, 'What are the two halves of the Ekene gas intercept?', '["Velocity +0.076897 and density -0.042553, as for the brine case.", "Velocity -0.09162755152933573 and density +0.028802610843132695.", "Velocity +0.028802610843132695 and density -0.09162755152933573.", "Velocity and density contribute equally at -0.0314 each."]'::jsonb, 2, 'The velocity half is positive because the gas sand is faster than the shale, and the density half is more than three times larger and negative.'),
  ('rockphysics', 'advanced', 'module', 'm02-intercept-and-gradient', 7, 'Change only the density from the brine case. What does the intercept become?', '["-0.091628, the density half on its own.", "-0.06282494068620303, the full gas value.", "+0.034344, unchanged, since density cancels in the intercept.", "-0.014730, so the density change alone flips the sign."]'::jsonb, 3, 'The velocity half stays at +0.076897 and the density half becomes -0.091628. The velocity change then more than quadruples the negative value.'),
  ('rockphysics', 'advanced', 'module', 'm02-intercept-and-gradient', 8, 'What are the two Ekene gradients?', '["-0.16766246414664518 and -0.2565633444602355.", "+0.16766246414664518 brine and -0.2565633444602355 gas.", "-0.2565633444602355 brine and -0.16766246414664518 gas.", "-0.409318 brine and -0.256563 gas."]'::jsonb, 0, 'Both are negative, meaning both reflections become more negative with offset, and the gas case is 53 percent steeper. The value -0.409318 is the gas case''s shear term alone.'),
  ('rockphysics', 'advanced', 'module', 'm02-intercept-and-gradient', 9, 'Why is the gradient negative for both Ekene cases?', '["The density falls across the interface in both cases.", "The sand is stiffer in shear than the shale in both cases.", "The compressional velocity rises across the interface.", "Shuey''s gradient is negative for any shale over sand interface."]'::jsonb, 1, 'A positive shear contrast enters with a factor of $-4(\bar v_s/\bar v_p)^2$ and drives the gradient negative. Shales have low shear stiffness, so this is the usual situation rather than a universal rule.'),
  ('rockphysics', 'advanced', 'module', 'm02-intercept-and-gradient', 10, 'What are the three terms of the Ekene gas gradient?', '["-0.028803 velocity, +0.123952 density, -0.409318 shear.", "+0.028803 velocity, -0.123952 density, +0.409318 shear.", "+0.028803 velocity, +0.123952 density, -0.409318 shear.", "+0.123952 velocity, +0.028803 density, -0.409318 shear."]'::jsonb, 2, 'They sum to -0.2565633444602355. The shear term is 2.7 times the other two combined and is the only negative one.'),
  ('rockphysics', 'advanced', 'module', 'm02-intercept-and-gradient', 11, 'Why is the density term positive in the gradient but negative in the intercept?', '["The gradient uses the reciprocal of the density contrast.", "The density contrast changes sign between the two coefficients.", "The weighting factor $w$ is negative for this interface.", "It enters as $-2w\\Delta\\rho/\\bar\\rho$ rather than $+\\tfrac{1}{2}\\Delta\\rho/\\bar\\rho$."]'::jsonb, 3, 'The minus sign flips it, so a falling density contributes negatively to the intercept and positively to the gradient. That opposition is part of why crossplotting the two separates fluid effects.'),
  ('rockphysics', 'advanced', 'module', 'm02-intercept-and-gradient', 12, 'What is the weighting factor $w$ for the Ekene gas case?', '["0.338195462, the square of the mean velocity ratio.", "0.581548, the mean velocity ratio itself.", "0.676391, twice the square of the ratio.", "1.352782, the effective weight on the shear contrast."]'::jsonb, 0, '$(1642.4879403056607/2824.3486140148097)^2$. The shear contrast is doubled inside the bracket, giving it an effective weight of -1.352782, about 2.7 times the compressional term''s one half.'),
  ('rockphysics', 'advanced', 'module', 'm02-intercept-and-gradient', 13, 'What happens to the gradient if the sand''s shear velocity is 10 percent low?', '["It moves from -0.256563 to -0.238977.", "It moves from -0.256563 to -0.100082.", "It is unchanged, since the shear velocity is fluid blind.", "It moves from -0.256563 to +0.084195."]'::jsonb, 1, 'Less than 40 percent of its correct value from a 10 percent error in one input. The value -0.238977 is the shear term after that error and +0.084195 is what an uncalibrated estimate gives.'),
  ('rockphysics', 'advanced', 'module', 'm02-intercept-and-gradient', 14, 'Where do the two Ekene cases sit on an intercept and gradient crossplot?', '["Both in the lower left, separated only along the gradient axis.", "Brine lower left, gas lower right; the fluid vector points down and right.", "Brine lower right, gas lower left; the fluid vector points down and left.", "Both in the lower right, separated only along the intercept axis."]'::jsonb, 2, 'The displacement is $\Delta A = -0.097169$ and $\Delta B = -0.088901$, almost equally split between the axes at 42.4 degrees below the negative intercept direction.'),
  ('rockphysics', 'advanced', 'module', 'm02-intercept-and-gradient', 15, 'What is a crossplot anomaly measured relative to?', '["The class boundaries drawn at the threshold.", "The origin of the crossplot at zero intercept and gradient.", "The fluid vector computed from the substitution.", "The local background trend of ordinary interfaces."]'::jsonb, 3, 'Shale over shale, shale over brine sand and sand over shale interfaces all fall along a trend. A point displaced from it in the fluid direction is a candidate hydrocarbon response.'),
  ('rockphysics', 'advanced', 'module', 'm03-the-class-flip', 1, 'What is a class I AVO response?', '["A large positive intercept, negative gradient.", "A large negative intercept with a negative gradient.", "An intercept near zero, dominated by the gradient.", "A negative intercept with a positive gradient."]'::jsonb, 0, 'The sand is harder than the shale, so the near offsets show a positive reflection that weakens with offset and often changes polarity. Typically a well consolidated sand.'),
  ('rockphysics', 'advanced', 'module', 'm03-the-class-flip', 2, 'What is a class III AVO response?', '["A large positive intercept with a negative gradient.", "A large negative intercept, negative gradient.", "An intercept near zero, dominated by the gradient.", "A negative intercept with a positive gradient."]'::jsonb, 1, 'The reflection is negative at all offsets and brightens with offset, which stacks well. These are the classic bright spots of unconsolidated young sands.'),
  ('rockphysics', 'advanced', 'module', 'm03-the-class-flip', 3, 'What is a class IV response and why does it matter?', '["An intercept exactly at zero, invisible on a stack.", "A positive intercept with a positive gradient, which brightens with offset.", "A negative intercept with a positive gradient.", "A response that changes polarity twice across the gather."]'::jsonb, 2, 'It occurs where the sand''s shear velocity is barely above the shale''s, so the shear term is weak and the positive density term wins. It breaks the rule of thumb that a gas sand brightens with offset.'),
  ('rockphysics', 'advanced', 'module', 'm03-the-class-flip', 4, 'How does the engine decide between class III and class IV?', '["By the sign of the gradient, once the intercept is below the threshold.", "By the size of the gradient relative to the intercept.", "By the size of the gradient relative to the intercept value.", "By the sign of the curvature coefficient."]'::jsonb, 0, 'Nothing hinges on the size of the gradient, only on its sign. A gradient that crosses zero moves a case between the two classes with no other change.'),
  ('rockphysics', 'advanced', 'module', 'm03-the-class-flip', 5, 'Which class is the Ekene brine case, and on what evidence?', '["Class I, on its gradient of -0.167662 being negative.", "Class I, on its intercept of 0.034344 being above 0.02.", "Class II, since its intercept is small.", "Class III, since it changes polarity within the gather."]'::jsonb, 1, 'The gradient plays no part in the call for a positive intercept. That asymmetry matters: the brine call used one number and the gas call used two.'),
  ('rockphysics', 'advanced', 'module', 'm03-the-class-flip', 6, 'Why is the Ekene brine case class I?', '["Its gradient is shallow enough to keep the reflection positive.", "The brine sand is softer than the shale, so the reflection is negative.", "The brine sand is harder than the shale above it.", "Its shear contrast against the shale is unusually small."]'::jsonb, 2, 'It is faster by 457 m/s and lighter by 200 kg/m3, and the velocity contrast wins. Consolidated sands are commonly class I for exactly that reason.'),
  ('rockphysics', 'advanced', 'module', 'm03-the-class-flip', 7, 'What happens to the Ekene brine reflection across the gather?', '["It changes sign near 10 degrees and then brightens.", "It falls from 0.0343 and stays positive throughout.", "It rises from 0.0343 as offset increases.", "It falls from 0.0343 and changes sign near 30 degrees."]'::jsonb, 3, 'A stack over the full offset range averages a positive near contribution against a negative far one, so a class I interface can look weak on a stack while being clearly visible on a gather.'),
  ('rockphysics', 'advanced', 'module', 'm03-the-class-flip', 8, 'How robust is the Ekene gas case class call?', '["Very. Class III at every threshold tried.", "Marginal. It becomes class II at a threshold of 0.04.", "Marginal. Its gradient is close enough to zero to become class IV.", "It cannot be assessed without knowing the background trend."]'::jsonb, 0, 'Its intercept of -0.062825 is more than three times the widest band, and its gradient of -0.256563 would have to reach zero to move it to class IV.'),
  ('rockphysics', 'advanced', 'module', 'm03-the-class-flip', 9, 'How robust is the Ekene brine case class call?', '["Very. Its intercept is more than three times the threshold.", "Marginal. Only 1.72 times the default threshold.", "Marginal, because its gradient is close to zero.", "It cannot change class, since a positive intercept is always class I."]'::jsonb, 1, 'At a threshold of 0.04 it is called class II rather than class I. One of the two Ekene class calls is a convention away from changing and the other is not.'),
  ('rockphysics', 'advanced', 'module', 'm03-the-class-flip', 10, 'What is the class II band and where does it come from?', '["A range of gradients within which the class is undefined.", "A range of $|A|$ derived from the noise level of a typical survey.", "A range of $|A|$ chosen by convention, usually 0.02.", "The range over which Shuey''s approximation is valid."]'::jsonb, 2, 'It reflects a judgement about what counts as a small intercept, made when the classification was introduced, and it has no derivation.'),
  ('rockphysics', 'advanced', 'module', 'm03-the-class-flip', 11, 'Which is larger at Ekene: the class threshold''s effect or Shuey''s approximation error?', '["Neither, since both are smaller than the intercept uncertainty.", "The approximation error, at 0.002175 against a 0.02 band.", "They are comparable, both about 0.002.", "The threshold, which renames a case entirely."]'::jsonb, 3, 'A convention with no derivation behind it has a larger effect on the reported result than the difference between an approximate theory and an exact one.'),
  ('rockphysics', 'advanced', 'module', 'm03-the-class-flip', 12, 'What should accompany a class call in a report?', '["The coefficients and the threshold used.", "The exact Zoeppritz value at 30 degrees.", "The tuning thickness for the survey.", "The background trend of the interval."]'::jsonb, 0, 'The coefficients are the quantities and the class is a summary of them; the threshold is a convention that travels invisibly with the label unless stated.'),
  ('rockphysics', 'advanced', 'module', 'm03-the-class-flip', 13, 'Where does the Ekene brine reflection change polarity?', '["26.92 degrees on the two term Shuey form.", "29.870555217606523 degrees on the exact solution.", "29.293564554985373 degrees on the three term Shuey form.", "It does not change polarity within 40 degrees."]'::jsonb, 1, 'All three angles are correct for their own method, and the question asks for the exact one. The three are spread over three degrees, which is large for a quantity used to design a stack.'),
  ('rockphysics', 'advanced', 'module', 'm03-the-class-flip', 14, 'Why is a polarity crossing hard to locate accurately?', '["The wavelet changes phase at the crossing angle.", "The exact solution goes complex near the crossing.", "The reflection is near zero there, so noise dominates.", "The wavelet stretches at far offsets, shifting the angle."]'::jsonb, 2, 'It applies to any quantity located by a zero crossing, and it implies the crossing should be found with the exact solution rather than an approximation.'),
  ('rockphysics', 'advanced', 'module', 'm03-the-class-flip', 15, 'What does a full offset stack do to a class I reflection at Ekene?', '["Reverses its polarity, since the far offsets dominate.", "Doubles it, since all offsets contribute with the same sign.", "Leaves it unchanged, since the crossing is beyond 40 degrees.", "Cancels roughly half of it."]'::jsonb, 3, 'Averaging the five tabulated exact values to 20 degrees gives 0.026711 and over the full five to 40 degrees gives 0.014671, so the full stack is about 55 percent of the limited one.'),
  ('rockphysics', 'advanced', 'module', 'm04-approximation-and-exact', 1, 'What does Zoeppritz''s solution give that Shuey''s does not?', '["An exact answer at any contrast and angle.", "A separation of rock properties from angle dependence.", "Two coefficients a gather can be fitted for.", "A form valid only below the critical angle."]'::jsonb, 0, 'It makes no approximation about the size of the contrasts or the angle. What it cannot do is be inverted, since a curve cannot determine six rock properties.'),
  ('rockphysics', 'advanced', 'module', 'm04-approximation-and-exact', 2, 'How many waves leave a compressional wave''s encounter with an interface?', '["Two: one reflected and one transmitted compressional wave.", "Four: reflected and transmitted, compressional and shear.", "Three: one reflected compressional and two transmitted waves.", "One, unless the incidence angle exceeds the critical angle."]'::jsonb, 1, 'Requiring displacement and stress to be continuous across the interface gives four equations in four unknowns, which is the system Zoeppritz solved.'),
  ('rockphysics', 'advanced', 'module', 'm04-approximation-and-exact', 3, 'Why is the exact solution not used for interpretation?', '["It becomes complex past the critical angle.", "It is too slow to evaluate on a modern gather.", "It cannot be inverted from a curve.", "It requires a shear velocity that is often missing."]'::jsonb, 2, 'Zoeppritz gives an amplitude from six rock properties, and a gather gives far less information than six properties. Shuey''s rearrangement buys invertibility, which is the trade.'),
  ('rockphysics', 'advanced', 'module', 'm04-approximation-and-exact', 4, 'Where is the Ekene critical angle for the gas case?', '["70.7 degrees, well outside the recorded offset range.", "30 degrees, which is why the capstone asks for that angle.", "40 degrees, at the edge of the modelled range.", "There is none, since the gas sand is slower than the shale above it."]'::jsonb, 0, '$\arcsin(2743/2905.6972)$. The imaginary part of the solution is zero throughout 0 to 40 degrees, which is not always true: a brine sand under a slow shale can go critical inside the offsets.'),
  ('rockphysics', 'advanced', 'module', 'm04-approximation-and-exact', 5, 'How large is the curvature bracket at each angle?', '["0.0833 at 20 degrees, 0.290913 at 30, 0.500 at 40.", "0.0154 at 20 degrees, 0.0833 at 30 and 0.290913 at 40.", "0.290913 at 20 degrees, 0.0833 at 30, 0.0154 at 40.", "It is constant at 0.0833 across the whole range."]'::jsonb, 1, '$\tan^2\theta - \sin^2\theta$ is negligible out to about 20 degrees and is not negligible at 40, which is inside the range modern surveys record.'),
  ('rockphysics', 'advanced', 'module', 'm04-approximation-and-exact', 6, 'What is the curvature coefficient C?', '["The shear contrast weighted by the velocity ratio squared.", "Half the fractional density contrast.", "Half the fractional velocity contrast.", "The product of the intercept and the gradient."]'::jsonb, 2, 'At Ekene it is 0.07689718997139491 brine and 0.028802610843132695 gas. The brine case carries 2.67 times the curvature, which explains why the approximation is worse on it.'),
  ('rockphysics', 'advanced', 'module', 'm04-approximation-and-exact', 7, 'How wrong is the two term form at 40 degrees for the Ekene gas case?', '["It is exact there, since the curvature term vanishes.", "0.000246, against 0.008625 for the three term form.", "0.002175, the same as at 30 degrees.", "0.008625, against 0.000246 for the three term form."]'::jsonb, 3, 'The third term is worth a factor of 35 in accuracy at the far offsets. It is nevertheless the two term form that should be fitted to a real gather.'),
  ('rockphysics', 'advanced', 'module', 'm04-approximation-and-exact', 8, 'Which Shuey form should be used for modelling and which for inversion?', '["Three terms for modelling, two for inversion.", "Two terms for modelling, three for inversion.", "Three terms for both, since accuracy always wins.", "Two terms for both, since a gather cannot resolve three."]'::jsonb, 0, 'There is no reason to approximate when all the inputs are known, and a noisy gather over a limited angle range cannot resolve three coefficients stably.'),
  ('rockphysics', 'advanced', 'module', 'm04-approximation-and-exact', 9, 'What bias does fitting two terms over a wide angle range introduce?', '["The intercept absorbs the curvature instead.", "The curvature is absorbed into the gradient.", "Both coefficients are biased equally.", "None, since the curvature term averages to zero."]'::jsonb, 1, 'A gradient measured from far offsets and one computed from rock properties are not comparable unless the same angle range and number of terms were used for both.'),
  ('rockphysics', 'advanced', 'module', 'm04-approximation-and-exact', 10, 'What is the gap between Shuey and the exact solution at 30 degrees for the gas case?', '["0.008625, the two term error at 40 degrees.", "0.000166, the same as at zero degrees.", "0.0021746462042847164, or 2.17 times the graded tolerance.", "Zero, since Shuey is exact at 30 degrees by construction."]'::jsonb, 2, 'That is why the capstone asks for the exact value at 30 degrees rather than the Shuey one: the approximation and the exact solution are distinguishable at the precision this tier works to.'),
  ('rockphysics', 'advanced', 'module', 'm04-approximation-and-exact', 11, 'Do Shuey and the exact solution agree at normal incidence?', '["No, and the gap grows monotonically with angle.", "Yes, exactly, since the angle terms all vanish.", "Yes, to within machine precision.", "No. They differ by 0.000166 for the gas case."]'::jsonb, 3, 'The intercept is the linearised impedance contrast rather than the impedance contrast itself. The gas gap also does not grow monotonically: it peaks near 30 degrees and shrinks by 40.'),
  ('rockphysics', 'advanced', 'module', 'm04-approximation-and-exact', 12, 'Which Ekene case does Shuey approximate worse, and by how much?', '["The brine case, at 0.005972 against 0.002192.", "The gas case, at 0.005972 against 0.002192.", "They are equally well approximated.", "The brine case, but only past 40 degrees."]'::jsonb, 0, 'That is the opposite of the intuition that a bigger anomaly is harder to approximate. Shuey''s error depends on how different the two rocks are, not on how large the reflection is.'),
  ('rockphysics', 'advanced', 'module', 'm04-approximation-and-exact', 13, 'Why is the approximation worse on the wet case?', '["Its reflection coefficient is larger at every angle.", "Its compressional contrast against the shale is 16.7 percent against 5.9.", "It changes polarity, and the linearisation fails near zero.", "Its shear contrast against the shale is the larger of the two, and Shuey linearises in shear."]'::jsonb, 1, 'Shuey''s error grows roughly with the square of the contrasts. The gas sand happens to be closer in velocity to the shale, so it is the easier interface to approximate even though it is the louder one.'),
  ('rockphysics', 'advanced', 'module', 'm04-approximation-and-exact', 14, 'What cheap diagnostic predicts where Shuey will be weak?', '["The gradient, which measures the shear contrast.", "The intercept, which measures the impedance contrast.", "The curvature coefficient, in one line.", "The critical angle, which bounds the valid range."]'::jsonb, 2, 'At Ekene the curvature ratio is 2.6698 and the maximum error ratio 2.7246, agreeing to within 2 percent. It gives advance warning before any comparison against the exact solution is run.'),
  ('rockphysics', 'advanced', 'module', 'm04-approximation-and-exact', 15, 'What should be reported as a value, and what as a coefficient?', '["Both as Shuey, since that is what a gather measures.", "Shuey values at each angle, and exact coefficients.", "Both as exact, since coefficients are approximations.", "Exact Zoeppritz values, and Shuey intercepts and gradients."]'::jsonb, 3, 'The coefficients are the common currency between a model and an inversion, and their approximate nature is what makes them comparable. Quoting a Shuey evaluation as the reflection coefficient introduces an avoidable error.'),
  ('rockphysics', 'advanced', 'module', 'm05-resolution', 1, 'What changes when a reservoir is a bed rather than a halfspace?', '["There are two reflections, and they can overlap.", "The reflection coefficient at the top changes.", "The incidence angle at the top is no longer well defined.", "The shear velocity stops mattering to the response."]'::jsonb, 0, 'A halfspace has one interface. A bed has a top and a base separated by twice the travel time through it, and when that separation is small the two arrive as a sum.'),
  ('rockphysics', 'advanced', 'module', 'm05-resolution', 2, 'Why do the top and base reflections of a reservoir usually have opposite signs?', '["The wavelet inverts on transmission through the bed.", "The impedance falls into the reservoir and rises out of it again.", "The base is recorded at a wider incidence angle.", "The base reflection is a multiple of the top."]'::jsonb, 1, 'That opposition is what the wedge fixture models, with plus 0.1 at the top and minus 0.1 at the base, and it is what produces tuning rather than simple cancellation.'),
  ('rockphysics', 'advanced', 'module', 'm05-resolution', 3, 'What is the tuning thickness?', '["The thickness at which the composite amplitude reaches zero.", "The thinnest bed whose top and base can be separated.", "The bed thickness at which the composite amplitude peaks.", "The wavelength of the wavelet in the reservoir."]'::jsonb, 2, 'At 25 Hz for this wavelet it is 16 ms, and the amplitude there is 0.1444934457540512 against an isolated 0.1, which is 44 percent brighter.'),
  ('rockphysics', 'advanced', 'module', 'm05-resolution', 4, 'How much brighter is a bed at tuning than an isolated interface?', '["44 percent.", "10 percent.", "Twice as bright.", "It is dimmer, at 70 percent of the isolated value."]'::jsonb, 0, '$0.1444934457540512 / 0.10000000149011612 = 1.4449$. Tuning does not perturb an amplitude by a few percent; it brightens it by nearly half.'),
  ('rockphysics', 'advanced', 'module', 'm05-resolution', 5, 'What are the three regions of the tuning curve?', '["Isolated below 8 ms, tuned 8 to 26 ms, collapsing above 30.", "Collapsing below 8 ms, tuned 8 to 26 ms, isolated above 30.", "Tuned below 8 ms, isolated 8 to 26 ms, collapsing above 30.", "Linear below 16 ms and flat above it."]'::jsonb, 1, 'At 2 ms only 30 percent of the isolated amplitude survives; above about 30 ms the two events are separable and the interface arithmetic applies directly.'),
  ('rockphysics', 'advanced', 'module', 'm05-resolution', 6, 'What is the theoretical tuning thickness for a Ricker wavelet?', '["$1000\\sqrt{6}/f$, or 2449.5 over f in ms.", "$1000/(2\\pi f)$, or 159.15 over f in ms.", "389.8484 divided by f, in ms.", "$1000/(4f)$, the quarter wavelength rule."]'::jsonb, 2, 'At 25 Hz that is 15.593936024673521 ms against the engine''s 16, the difference being the 1 ms sampling grid. The Kallweit and Wood form $1/(2.6f)$ gives 15.38.'),
  ('rockphysics', 'advanced', 'module', 'm05-resolution', 7, 'What tuning thicknesses does the engine report at 15, 25, 40 and 50 Hz?', '["24, 16, 10 and 8 ms.", "16, 26, 8 and 10 ms.", "26, 16, 12 and 10 ms.", "26, 16, 10 and 8 ms."]'::jsonb, 3, 'Each is the theoretical value rounded up to the 1 ms grid, and the largest discrepancy is 0.41 ms at 25 Hz.'),
  ('rockphysics', 'advanced', 'module', 'm05-resolution', 8, 'What happens to the tuning thickness if the reflection coefficients double?', '["Nothing. Only the amplitude doubles.", "It doubles as well, since the curve scales.", "It halves, since the interference is stronger.", "It moves to the nearest grid sample above the new value."]'::jsonb, 0, 'Running the same wedge with plus and minus 0.08 gives 16 ms and a peak of 0.1155947595834732, against 16 ms and 0.1444934457540512 for plus and minus 0.1. The ratio is 1.25, exactly 0.1 over 0.08.'),
  ('rockphysics', 'advanced', 'module', 'm05-resolution', 9, 'Which course established that tuning depends only on the wavelet?', '["This tier, on the plus and minus 0.1 pair.", "The Seismolord Expert tier, on a different pair.", "The Rock Physics Associate tier, from the Ricker wavelet.", "The Mapping Expert tier, from the resolution of a grid."]'::jsonb, 1, 'It derived the law that a Ricker depends on frequency and thickness only through their product, using a plus and minus 0.08 pair. This tier confirms it on a different fixture rather than re-deriving it.'),
  ('rockphysics', 'advanced', 'module', 'm05-resolution', 10, 'What do the products of frequency and tuning thickness come to at Ekene?', '["390 at every frequency, exactly.", "400 at every frequency, exactly.", "400 at 25, 40 and 50 Hz, and 390 at 15 Hz.", "They vary with the reflection coefficients as well as the frequency."]'::jsonb, 2, 'The three at 400 give an identical peak of 0.1444934457540512 and the 15 Hz case gives a higher one, because 390 sits nearer the ideal 389.8484.'),
  ('rockphysics', 'advanced', 'module', 'm05-resolution', 11, 'How thick is the tuning thickness in metres for the Ekene gas sand?', '["11.6 m at 25 Hz, from the half thickness.", "16 m at 25 Hz, since 16 ms is the tuning thickness.", "46.5 m at 25 Hz, from the one way time.", "23.2 m at 25 Hz, using the two way travel time."]'::jsonb, 3, '$16 \times 2905.6972280296195 / 2000$, using two way time. Many producing sands are thinner than that, and the number scales with velocity and inversely with frequency.'),
  ('rockphysics', 'advanced', 'module', 'm05-resolution', 12, 'Why is an amplitude map not a fluid map?', '["It mixes the interface contrast with the bed thickness.", "It is recorded at a single offset rather than a stack.", "It has not been corrected for the wavelet phase.", "It measures the base reflection rather than the top."]'::jsonb, 0, 'The recorded amplitude is approximately the interface coefficient times a tuning function. A prospect thinning from 40 m to 5 m would show a strong centre fading to nothing with identical rock throughout.'),
  ('rockphysics', 'advanced', 'module', 'm05-resolution', 13, 'What is a tuning artefact on an amplitude map?', '["A dim patch where the wavelet phase reverses.", "A bright ring where the reservoir passes through tuning thickness.", "A bright centre where the reservoir is thickest.", "A ring of noise at the edge of the survey."]'::jsonb, 1, 'It has nothing to do with the fluid, and it is why amplitude maps are normally accompanied by isochron maps. If the bright ring coincides with the tuning thickness contour, that is the explanation.'),
  ('rockphysics', 'advanced', 'module', 'm05-resolution', 14, 'Why is a tuning correction least reliable where it is most needed?', '["The correction assumes a symmetric reflection pair, which fails at depth.", "The wavelet frequency is unknown below tuning.", "Below tuning the apparent thickness stops tracking the true one.", "Thin beds are usually outside the survey''s fold coverage."]'::jsonb, 2, 'The isochron is measured from the same data, so the correction depends on a thickness that the data can no longer resolve. It also assumes the base reflection is roughly the negative of the top.'),
  ('rockphysics', 'advanced', 'module', 'm05-resolution', 15, 'How does tuning affect the intercept and the gradient differently?', '["It affects both identically, so their ratio is preserved.", "Tuning affects the gradient only, since the intercept is at zero offset.", "Tuning affects the intercept only, since it is an amplitude effect.", "A far offset ray sees a thicker bed than a vertical one."]'::jsonb, 3, 'The path through the bed grows as $1/\cos\theta$, 1.155 at 30 degrees, so a bed at vertical tuning is 15 percent above tuning for a far ray. Since class is decided by the sign of the gradient, a thickness bias can change a class.'),
  ('rockphysics', 'advanced', 'module', 'm06-the-avo-workflow', 1, 'What is the first step of the AVO workflow?', '["Fixing both rocks, the overburden as well as the reservoir.", "Computing the Shuey intercept and gradient for each fluid case.", "Classifying each case against a stated threshold.", "Computing the tuning thickness for the survey."]'::jsonb, 0, 'Every number in this tier is a property of a pair of rocks, and the shale matters as much as the sand. A model built on an assumed overburden is entirely self consistent and possibly entirely wrong.'),
  ('rockphysics', 'advanced', 'module', 'm06-the-avo-workflow', 2, 'Why compute the normal incidence reflection separately?', '["It is what a stacked section shows directly.", "It is exact and it checks the sign of everything after it.", "It is the only value the capstone grades exactly.", "Shuey''s intercept cannot be computed without it."]'::jsonb, 1, 'At Ekene it gives 0.034457 and -0.0629911815139045, so the sign flips between the cases. The Shuey intercept is the linearised version and differs in the fourth decimal.'),
  ('rockphysics', 'advanced', 'module', 'm06-the-avo-workflow', 3, 'Which workflow step is most often skipped?', '["Classifying the two cases.", "Computing the coefficients for both fluid cases.", "Comparing Shuey against the exact.", "Computing the normal incidence reflection."]'::jsonb, 2, 'At Ekene the largest departure is 0.005972 for the brine case, which is 17 percent of its intercept, and knowing that prevents over-interpreting a mismatch between a model and data.'),
  ('rockphysics', 'advanced', 'module', 'm06-the-avo-workflow', 4, 'Which step fails most expensively at Ekene?', '["An uncalibrated shear estimate, which can change the class.", "An assumed overburden, which changes every coefficient computed.", "Omitting the threshold from the class call.", "Using the two term form to find the polarity crossing."]'::jsonb, 0, 'It moves the gradient from -0.256563 to +0.084195, which is class IV rather than class III. The overburden matters too and at least it is usually logged.'),
  ('rockphysics', 'advanced', 'module', 'm06-the-avo-workflow', 5, 'Which check compares the intercept against something independent?', '["The gradient decomposition into three terms.", "The impedance contrast.", "The exact solution at zero degrees.", "The class against the sign of the intercept."]'::jsonb, 1, 'They should agree to the third or fourth decimal. A larger disagreement means the linearisation is being pushed harder than it should be anywhere.'),
  ('rockphysics', 'advanced', 'module', 'm06-the-avo-workflow', 6, 'What does the gradient decomposition check catch?', '["A missing curvature term.", "Transposed rock pairs.", "Sign errors in the weighting factor.", "An incorrect class threshold."]'::jsonb, 2, 'It also tells you which contrast is driving the answer whether or not it passes. At Ekene the three terms sum to -0.256563 and the shear term dominates.'),
  ('rockphysics', 'advanced', 'module', 'm06-the-avo-workflow', 7, 'What must the exact solution give at zero degrees?', '["A complex value with zero imaginary part.", "Exactly the Shuey intercept.", "Zero, since there is no offset.", "Exactly the impedance contrast."]'::jsonb, 3, 'The exact solution is complicated enough that errors in it are hard to spot any other way, which makes this a valuable check.'),
  ('rockphysics', 'advanced', 'module', 'm06-the-avo-workflow', 8, 'What must the imaginary part of the exact solution be at Ekene?', '["Zero throughout 0 to 40 degrees.", "Non zero beyond 30 degrees, where the solution goes complex.", "Equal to the real part at the critical angle.", "Undefined, since the solution is real by construction."]'::jsonb, 0, 'The critical angle is 70.7 degrees, far outside the recorded range. A non zero imaginary part inside it would mean a critical angle is present or the implementation is wrong.'),
  ('rockphysics', 'advanced', 'module', 'm06-the-avo-workflow', 9, 'Which trivial check catches a transposed rock pair?', '["The tuning thickness against theory.", "The class against the sign of the intercept.", "The gradient decomposition.", "The imaginary part of the exact solution."]'::jsonb, 1, 'A positive intercept must give class I or II and a negative one class II, III or IV. Transposing the pair reverses every sign and produces plausible looking numbers.'),
  ('rockphysics', 'advanced', 'module', 'm06-the-avo-workflow', 10, 'What three things do the AVO checks not see?', '["A missing curvature term, a wrong angle range, and noise.", "A sign error, a transposed pair, and a wrong threshold.", "A wrong overburden, a wrong substitution, or a thin bed.", "A critical angle, a complex solution, or an evanescent transmitted wave."]'::jsonb, 2, 'All six checks pass on a bed far below tuning, and the modelled coefficients then describe something the data does not contain.'),
  ('rockphysics', 'advanced', 'module', 'm06-the-avo-workflow', 11, 'How many fields does this capstone grade?', '["Eight, four per fluid case.", "Six, as every other tier does.", "Four, two coefficients for each fluid case.", "Seven, one more than the other tiers."]'::jsonb, 3, 'Four coefficients, a class, an exact value at one angle and a tuning thickness. Two cases with two coefficients each is why it needs more than six.'),
  ('rockphysics', 'advanced', 'module', 'm06-the-avo-workflow', 12, 'Which capstone field cannot be answered from Shuey''s form?', '["The exact Zoeppritz value at 30 degrees.", "The gas case gradient.", "The gas case class.", "The wedge tuning thickness."]'::jsonb, 0, 'Shuey gives -0.12456555923100084 there against an exact -0.12239091302671612, a gap of 0.0021746462042847164 which is 2.17 times the tolerance.'),
  ('rockphysics', 'advanced', 'module', 'm06-the-avo-workflow', 13, 'How should the gas class be reported on this capstone?', '["As the Roman numeral III.", "As the number 3.", "As the pair of coefficients that produced it.", "As class III at a threshold of 0.02."]'::jsonb, 1, 'The field wants a number between 1 and 4. Reporting it as a Roman numeral is one of the three common errors on this capstone.'),
  ('rockphysics', 'advanced', 'module', 'm06-the-avo-workflow', 14, 'Which check catches a transposition between the two fluid cases?', '["The tuning thickness is 16 ms at 25 Hz.", "Both gradients are negative and the gas one is 53 percent steeper.", "The brine intercept is positive and the gas one negative.", "The class is I for one case and III for the other."]'::jsonb, 2, 'A sign check on the two intercepts catches it immediately. Both gradients being negative does not distinguish the cases, and the classes are only labels on those coefficients.'),
  ('rockphysics', 'advanced', 'module', 'm06-the-avo-workflow', 15, 'What is the largest outstanding limit after this tier?', '["The class threshold is a convention.", "The shear modulus is treated as fluid blind.", "The tuning thickness is computed on a 1 ms grid.", "Plane waves at a plane interface."]'::jsonb, 3, 'Real reflections come from curved rough surfaces in anisotropic attenuating media, recorded through a processing sequence that changes amplitudes. None of that is in this tier.'),
  ('rockphysics', 'advanced', 'final', null, 1, 'Which set of seven values is the Ekene AVO capstone answer key?', '["0.034344, -0.167662, -0.062825, -0.256563, 3, -0.122391, 16.", "0.034457, -0.167662, -0.062991, -0.256563, 3, -0.124566, 16.", "0.034344, -0.167662, -0.062825, -0.256563, 1, -0.122391, 16.", "-0.062825, -0.256563, 0.034344, -0.167662, 3, -0.122391, 16."]'::jsonb, 0, 'The second set uses exact normal incidence values in place of the intercepts and the Shuey value at 30 degrees; the third gives the brine class; the fourth transposes the two fluid cases.'),
  ('rockphysics', 'advanced', 'final', null, 2, 'What does this tier add to the tier below?', '["A property model across the field.", "An overburden, turning two rocks into two interfaces.", "A saturation height model for the reservoir.", "A processing sequence turning reflectivity into a trace."]'::jsonb, 1, 'A reflection is a property of a boundary rather than of a rock, and the tier below produced rocks.'),
  ('rockphysics', 'advanced', 'final', null, 3, 'What are the Ekene shale''s logged properties?', '["2743 m/s, 1394 m/s, 2450 kg/m3.", "2905.6972280296195 m/s, 1890.9758806113214 m/s, 2038.7104517793223 kg/m3.", "3200 m/s, 1800 m/s, 2250 kg/m3.", "2743 m/s, 1800 m/s, 2250 kg/m3."]'::jsonb, 0, 'The other two triples are the gas sand and the logged brine sand. The same shale sits over both, so every difference between the responses is a fluid difference.'),
  ('rockphysics', 'advanced', 'final', null, 4, 'Is the Ekene gas sand faster or slower than the shale?', '["Slower, by 162.69722802961946 m/s.", "Faster, by 162.69722802961946 m/s.", "The same speed, within a metre per second.", "Slower, by 457 m/s."]'::jsonb, 1, 'The velocity contrast stays positive. The reflection is negative anyway, because the density falls by 411.29 kg/m3 across the interface.'),
  ('rockphysics', 'advanced', 'final', null, 5, 'What flips the sign of the Ekene reflection?', '["The shear contrast reversing between the fluid cases.", "The velocity contrast reversing across the interface.", "The density contrast outweighing the velocity.", "The critical angle falling inside the recorded range."]'::jsonb, 2, 'The gas sand is 5.9 percent faster and 16.8 percent lighter than the shale, and impedance is the product.'),
  ('rockphysics', 'advanced', 'final', null, 6, 'What are the exact normal incidence reflections at Ekene?', '["0.076897 brine and 0.028803 gas.", "0.03434399848203321 brine and -0.06282494068620303 gas.", "0.034457 brine and -0.124566 gas.", "0.034457 brine and -0.0629911815139045 gas."]'::jsonb, 3, 'The second pair is the Shuey intercepts, which are the linearised versions and differ in the fourth decimal.'),
  ('rockphysics', 'advanced', 'final', null, 7, 'Could any porosity make the Ekene gas reflection positive?', '["No. The gas impedance peaks below the shale''s.", "Yes, below a porosity of about 0.10.", "Yes, above a porosity of about 0.40.", "Yes, but only outside the range the engine accepts."]'::jsonb, 0, 'It rises with porosity to a maximum near 0.41 and falls again, never reaching 6,720,350. The sign is robust; the impedance sits 16.1 percent below the shale''s at a porosity of 0.20 and 9.9 percent below it at 0.30.'),
  ('rockphysics', 'advanced', 'final', null, 8, 'What did Shuey''s rewrite achieve?', '["It extended the exact solution past the critical angle.", "It separated the rocks from the angle.", "It removed the shear velocity from the problem.", "It made the exact solution faster to evaluate."]'::jsonb, 1, 'Three coefficients from the rocks and three functions of angle. That separation is what lets a gather be fitted for two rock properties.'),
  ('rockphysics', 'advanced', 'final', null, 9, 'Which property is absent from the intercept?', '["The compressional velocity.", "The density.", "The shear velocity.", "The porosity."]'::jsonb, 2, 'At normal incidence there is no shear motion at the interface. The shear velocity appears twice in the gradient instead, which is why the gradient carries fluid information.'),
  ('rockphysics', 'advanced', 'final', null, 10, 'What are the two halves of the Ekene gas intercept?', '["Both about -0.0314, contributing equally.", "Velocity -0.09162755152933573, density +0.028802610843132695.", "Velocity +0.076897, density -0.042553.", "Velocity +0.028802610843132695, density -0.09162755152933573."]'::jsonb, 3, 'The velocity half is positive because the gas sand is faster than the shale, and the density half is more than three times larger.'),
  ('rockphysics', 'advanced', 'final', null, 11, 'Change only the density from the brine case. What is the intercept?', '["-0.014730, so density alone flips it.", "-0.06282494068620303, the full gas value.", "+0.034344, unchanged.", "-0.091628, the density half alone."]'::jsonb, 0, 'The velocity half stays at +0.076897 and the density half becomes -0.091628. The velocity change then more than quadruples the negative value.'),
  ('rockphysics', 'advanced', 'final', null, 12, 'What are the two Ekene gradients?', '["+0.16766246414664518 and -0.2565633444602355.", "-0.16766246414664518 and -0.2565633444602355.", "-0.2565633444602355 and -0.16766246414664518.", "-0.409318 and -0.256563."]'::jsonb, 1, 'Brine first, gas second. Both are negative and the gas case is 53 percent steeper; -0.409318 is the gas case''s shear term alone.'),
  ('rockphysics', 'advanced', 'final', null, 13, 'What are the three terms of the Ekene gas gradient?', '["-0.028803 velocity, +0.123952 density, -0.409318 shear.", "+0.028803 velocity, -0.123952 density, +0.409318 shear.", "+0.028803 velocity, +0.123952 density, -0.409318 shear.", "+0.123952 velocity, +0.028803 density, -0.409318 shear."]'::jsonb, 2, 'The shear term is 2.7 times the other two combined, and the density term is positive, pushing the gradient up rather than down.'),
  ('rockphysics', 'advanced', 'final', null, 14, 'Why is the density term positive in the gradient?', '["The gradient uses the reciprocal of the density contrast.", "The density contrast is positive across this interface.", "The weighting factor is negative for a shale over sand pair.", "It enters as $-2w\\Delta\\rho/\\bar\\rho$ rather than $+\\tfrac{1}{2}\\Delta\\rho/\\bar\\rho$."]'::jsonb, 3, 'Intercept and gradient respond to density in opposite directions, which is part of why crossplotting the two separates fluid effects.'),
  ('rockphysics', 'advanced', 'final', null, 15, 'What happens to the gradient with an uncalibrated shear estimate?', '["It goes to +0.084195, making the case class IV.", "It goes to -0.100082, still class III.", "It is unchanged, since the shear modulus is fluid blind.", "It doubles to -0.513127, deepening the class III response."]'::jsonb, 0, 'A shear velocity of 1446.343832922053 collapses the contrast against the shale from 496.98 to 52.34 m/s. The value -0.100082 is what a 10 percent error gives.'),
  ('rockphysics', 'advanced', 'final', null, 16, 'Where do the two Ekene cases sit on a crossplot?', '["Brine lower left, gas lower right.", "Brine lower right, gas lower left.", "Both lower left, separated along the gradient axis.", "Both lower right, separated along the intercept axis."]'::jsonb, 1, 'The fluid displacement is -0.097169 in intercept and -0.088901 in gradient, at 42.4 degrees below the negative intercept direction.'),
  ('rockphysics', 'advanced', 'final', null, 17, 'What is a crossplot anomaly measured against?', '["The fluid vector from the substitution.", "The origin of the crossplot.", "The local background trend of interfaces.", "The class boundaries at the threshold."]'::jsonb, 2, 'Shale over shale, shale over brine sand and sand over shale interfaces all fall along a trend, and a displacement from it in the fluid direction is the candidate.'),
  ('rockphysics', 'advanced', 'final', null, 18, 'What is a class I response?', '["Negative intercept, positive gradient.", "Negative intercept, negative gradient.", "Intercept near zero.", "Positive intercept, negative gradient."]'::jsonb, 3, 'The sand is harder than the shale, so the near offsets are positive and the reflection often changes polarity within the gather.'),
  ('rockphysics', 'advanced', 'final', null, 19, 'What is a class IV response and why does it matter?', '["Negative intercept with a positive gradient, dimming with offset.", "Positive intercept with a positive gradient, brightening with offset.", "An intercept of exactly zero, invisible on a stack.", "A response that changes polarity twice across the gather."]'::jsonb, 0, 'It occurs where the sand''s shear velocity is barely above the shale''s, and it breaks the rule of thumb that a gas sand brightens with offset.'),
  ('rockphysics', 'advanced', 'final', null, 20, 'How robust are the two Ekene class calls?', '["Both robust at every threshold tried.", "Gas robust throughout; brine class II at 0.04.", "Brine robust; gas becomes class IV at a wider threshold.", "Neither, since both intercepts are near the boundary."]'::jsonb, 1, 'The gas intercept is more than three times the widest band and the brine intercept only 1.72 times the default. The two calls are not equally informed.'),
  ('rockphysics', 'advanced', 'final', null, 21, 'Where does the class II band come from?', '["The range over which Shuey''s form is valid.", "The noise level of a typical modern survey.", "A convention with no derivation, usually 0.02.", "The intercept uncertainty from a standard inversion."]'::jsonb, 2, 'It reflects a judgement about what counts as a small intercept, made when the classification was introduced, and it travels invisibly with the label unless stated.'),
  ('rockphysics', 'advanced', 'final', null, 22, 'Which is larger at Ekene: the threshold''s effect or Shuey''s error?', '["Neither, both being below the intercept uncertainty.", "The approximation error, at 0.002175.", "They are comparable in size.", "The threshold, which renames a case entirely."]'::jsonb, 3, 'A convention with no derivation has a larger effect on the reported result than the difference between an approximate theory and an exact one.'),
  ('rockphysics', 'advanced', 'final', null, 23, 'Where does the Ekene brine reflection change polarity?', '["29.870555217606523 degrees, on the exact solution.", "26.92 degrees, on the two term form.", "29.293564554985373 degrees, on the three term form.", "It does not, within 40 degrees."]'::jsonb, 0, 'All three angles are correct for their own method and the question asks for the exact one. They are spread over three degrees, which is large for a quantity used to design a stack.'),
  ('rockphysics', 'advanced', 'final', null, 24, 'Why is a polarity crossing hard to locate?', '["The exact solution goes complex near the crossing.", "The reflection is near zero there.", "The wavelet changes phase at the crossing.", "The gradient is undefined where the reflection is zero."]'::jsonb, 1, 'It applies to any quantity located by a zero crossing, and it implies the crossing should be found with the exact solution rather than an approximation.'),
  ('rockphysics', 'advanced', 'final', null, 25, 'What does a full offset stack do to the Ekene brine reflection?', '["Leaves it unchanged, the crossing being beyond 40 degrees.", "Doubles it, since every offset adds with the same sign.", "Cancels about half of it, from 0.026711 to 0.014671.", "Reverses its polarity, the far offsets dominating."]'::jsonb, 2, 'Averaging the five tabulated exact values to 20 degrees gives 0.026711 and all five to 40 gives 0.014671, so a full stack is about 55 percent of a limited one.'),
  ('rockphysics', 'advanced', 'final', null, 26, 'What does Zoeppritz give that Shuey does not?', '["A form that stays real past the critical angle.", "Two coefficients a gather can be fitted for.", "A separation of the rocks from the geometry.", "An exact answer at any contrast and angle."]'::jsonb, 3, 'What it cannot do is be inverted, since a curve cannot determine six independent rock properties. Shuey''s approximation buys invertibility.'),
  ('rockphysics', 'advanced', 'final', null, 27, 'Where is the Ekene critical angle for the gas case?', '["70.7 degrees, far outside the recorded range.", "30 degrees, which is why the capstone uses that angle.", "40 degrees, at the edge of the modelled range.", "There is none, the gas sand being slower than the shale."]'::jsonb, 0, '$\arcsin(2743/2905.6972)$. The imaginary part of the solution is zero throughout 0 to 40 degrees, which is not always the case.'),
  ('rockphysics', 'advanced', 'final', null, 28, 'How wrong is the two term form at 40 degrees for the gas case?', '["0.000246, against 0.008625 for three terms.", "0.008625, against 0.000246 for three terms.", "0.002175, the same as at 30 degrees.", "It is exact there."]'::jsonb, 1, 'The third term is worth a factor of 35 in accuracy at the far offsets, and it is still the two term form that should be fitted to a real gather.'),
  ('rockphysics', 'advanced', 'final', null, 29, 'Which form for modelling and which for inversion?', '["Three for both.", "Two to model, three to invert.", "Three terms to model, two to invert.", "Two for both."]'::jsonb, 2, 'There is no reason to approximate when the inputs are known, and a noisy gather over a limited angle range cannot resolve three coefficients stably.'),
  ('rockphysics', 'advanced', 'final', null, 30, 'What is the gap between Shuey and exact at 30 degrees for the gas case?', '["Zero, Shuey being exact at 30 degrees.", "0.000166, the same as at zero degrees.", "0.008625, the two term error at 40 degrees.", "0.0021746462042847164, 2.17 times the tolerance."]'::jsonb, 3, 'That is why the capstone asks for the exact value at 30 degrees rather than the Shuey one.'),
  ('rockphysics', 'advanced', 'final', null, 31, 'Do Shuey and the exact solution agree at normal incidence?', '["No. They differ by 0.000166 for the gas case.", "Yes, exactly, since the angle terms vanish.", "Yes, to machine precision.", "No, and the gap grows monotonically with angle."]'::jsonb, 0, 'The intercept is the linearised impedance contrast rather than the contrast itself. The gas gap also peaks near 30 degrees and shrinks again by 40.'),
  ('rockphysics', 'advanced', 'final', null, 32, 'Which case does Shuey approximate worse at Ekene?', '["The gas case, at 0.005972 against 0.002192.", "The brine case, 0.005972 against 0.002192.", "Both equally.", "The brine case, but only beyond 40 degrees."]'::jsonb, 1, 'Shuey''s error depends on how different the two rocks are rather than how large the reflection is, and the brine sand differs from the shale by 16.7 percent in velocity against 5.9.'),
  ('rockphysics', 'advanced', 'final', null, 33, 'What cheap diagnostic predicts where Shuey will be weak?', '["The gradient, measuring the shear contrast.", "The intercept, measuring the impedance contrast.", "The curvature coefficient, in one line.", "The critical angle, bounding the valid range."]'::jsonb, 2, 'At Ekene the curvature ratio is 2.6698 and the maximum error ratio 2.7246, agreeing to within 2 percent.'),
  ('rockphysics', 'advanced', 'final', null, 34, 'What should be reported as a value and what as a coefficient?', '["Both as Shuey.", "Shuey values as values, exact results as coefficients.", "Both as exact.", "Exact as values, Shuey as coefficients."]'::jsonb, 3, 'The coefficients are the common currency between a model and an inversion. Quoting a Shuey evaluation as the reflection coefficient introduces an avoidable error.'),
  ('rockphysics', 'advanced', 'final', null, 35, 'What is the Ekene tuning thickness and the amplitude there?', '["16 ms at 25 Hz, with a peak of 0.1444934457540512.", "16 ms at 25 Hz, with a peak of 0.10000000149011612.", "10 ms at 25 Hz, with a peak of 0.1444934457540512.", "26 ms at 25 Hz, with a peak of 0.14462600648403168."]'::jsonb, 0, 'The isolated value is 0.10000000149011612, so a bed at tuning records 44 percent brighter. The other pairs are the 40 Hz and 15 Hz cases.'),
  ('rockphysics', 'advanced', 'final', null, 36, 'What happens to the tuning thickness if the reflection coefficients double?', '["It doubles too.", "Nothing. Only the amplitude doubles.", "It halves.", "It moves to the next grid sample."]'::jsonb, 1, 'Plus and minus 0.08 gives 16 ms and a peak of 0.1155947595834732; plus and minus 0.1 gives 16 ms and 0.1444934457540512. The ratio is 1.25, exactly 0.1 over 0.08.'),
  ('rockphysics', 'advanced', 'final', null, 37, 'Which course established that tuning belongs to the wavelet?', '["The Rock Physics Associate tier.", "This tier, on the plus and minus 0.1 pair.", "The Seismolord Expert tier.", "The Mapping Expert tier."]'::jsonb, 2, 'It derived the law that a Ricker depends on frequency and thickness only through their product. This tier confirms it on a different fixture rather than re-deriving it.'),
  ('rockphysics', 'advanced', 'final', null, 38, 'What are the frequency and thickness products at Ekene?', '["They depend on the reflection coefficients too.", "400 at every frequency.", "390 at every frequency.", "400 at 25, 40 and 50 Hz, and 390 at 15 Hz."]'::jsonb, 3, 'The three at 400 share an identical peak and the 15 Hz case is higher, because 390 is nearer the ideal 389.8484.'),
  ('rockphysics', 'advanced', 'final', null, 39, 'What is the Ekene tuning thickness in metres?', '["23.2 m at 25 Hz.", "16 m at 25 Hz.", "46.5 m at 25 Hz.", "11.6 m at 25 Hz."]'::jsonb, 0, '$16 \times 2905.6972280296195/2000$, using two way time. Many producing sands are thinner than that.'),
  ('rockphysics', 'advanced', 'final', null, 40, 'Why is an amplitude map not a fluid map?', '["It is recorded at one offset rather than stacked.", "It mixes the contrast with the thickness.", "It has not been corrected for wavelet phase.", "It measures the base rather than the top reflection."]'::jsonb, 1, 'A prospect thinning from 40 m to 5 m would show a strong centre fading to nothing with identical rock throughout, and reading that as a fluid map implies a different volume and different wells.'),
  ('rockphysics', 'advanced', 'final', null, 41, 'How does tuning affect the intercept and gradient differently?', '["It affects the intercept only, being an amplitude effect.", "It affects the gradient only, the intercept being at zero offset.", "A far offset ray travels further through the bed.", "It affects both identically, preserving their ratio."]'::jsonb, 2, 'The path grows as $1/\cos\theta$, 1.155 at 30 degrees, so a bed at vertical tuning is 15 percent above tuning for a far ray. Since class is decided by the sign of the gradient, a thickness bias can change a class.'),
  ('rockphysics', 'advanced', 'final', null, 42, 'What four conditions must hold for this tier''s coefficients to describe a recorded amplitude?', '["Right class, right threshold, right crossing angle, right stack.", "Right rocks, right overburden, zero noise, zero anisotropy.", "Right porosity, right fluid, right frequency, right offset range.", "Right rocks, shear, thickness and approximation."]'::jsonb, 3, 'Fail any one and the model and the data disagree for a reason that has nothing to do with fluid.');
